using System.Collections.ObjectModel;

namespace PredatorControlApp;

public sealed record OemGpuOverclockOffsets(string PciSubsystemId, int QuietCoreMhz, int DefaultCoreMhz, int ExtremeCoreMhz, int TurboCoreMhz, int QuietRamMhz, int DefaultRamMhz, int ExtremeRamMhz, int TurboRamMhz)
{
    public (int CoreMhz, int RamMhz) GetSafeOffsetsForMode(byte mode) => mode switch
    {
        0 or 6 => (Math.Clamp(QuietCoreMhz, 0, 100), Math.Clamp(QuietRamMhz, 0, 200)),
        1 => (Math.Clamp(DefaultCoreMhz, 0, 100), Math.Clamp(DefaultRamMhz, 0, 200)),
        4 => (Math.Clamp(ExtremeCoreMhz, 0, 100), Math.Clamp(ExtremeRamMhz, 0, 200)),
        5 => (Math.Clamp(TurboCoreMhz, 0, 100), Math.Clamp(TurboRamMhz, 0, 200)),
        _ => (0, 0)
    };
}

