    public static OemModelCatalogEntry? TryGetModel(string? normalizedModel) =>
        !string.IsNullOrWhiteSpace(normalizedModel) && Entries.TryGetValue(normalizedModel.Trim(), out var entry) ? entry : null;

    public static (int CoreMhz, int RamMhz) GetSafeGpuOffsets(string? normalizedModel, string? pciHardwareId, byte powerMode)
    {
        var entry = TryGetModel(normalizedModel);
        if (entry == null || entry.GpuProfiles.Count == 0) return (0, 0);
        if (!string.IsNullOrWhiteSpace(pciHardwareId))
        {
            var exact = entry.GpuProfiles.FirstOrDefault(g => pciHardwareId.Contains(g.PciSubsystemId, StringComparison.OrdinalIgnoreCase));
            if (exact != null) return exact.GetSafeOffsetsForMode(powerMode);
        }
        return entry.GpuProfiles[0].GetSafeOffsetsForMode(powerMode);
    }
